import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

import { describe, expect, it } from 'vitest'

import { equipmentLabels, muscleLabels } from '../src/entities/exercise/config/labels.ts'
import type { Exercise } from '../src/entities/exercise/model/types.ts'

const CATALOG = join(import.meta.dirname, '..', 'public', 'catalog', 'exercises.json')

// The catalog is generated by `pnpm catalog`; without it there is nothing to check.
describe.skipIf(!existsSync(CATALOG))('built catalog', () => {
  const catalog = existsSync(CATALOG)
    ? (JSON.parse(readFileSync(CATALOG, 'utf8')) as Exercise[])
    : []

  it('has a Russian label for every muscle and equipment value', () => {
    const muscles = new Set(catalog.flatMap((e) => [...e.primaryMuscles, ...e.secondaryMuscles]))
    const equipment = new Set(catalog.flatMap((e) => (e.equipment ? [e.equipment] : [])))

    expect([...muscles].sort()).toEqual(Object.keys(muscleLabels).sort())
    expect([...equipment].sort()).toEqual(Object.keys(equipmentLabels).sort())
  })

  it('keeps technique steps out of the list, one entry per exercise in instructions.json', () => {
    const steps = JSON.parse(
      readFileSync(join(CATALOG, '..', 'instructions.json'), 'utf8'),
    ) as Record<string, string[]>

    expect(catalog.some((e) => 'instructions' in e)).toBe(false)
    expect(Object.keys(steps).sort()).toEqual(catalog.map((e) => e.id).sort())
  })

  it('uses only the four kinds', () => {
    const kinds = new Set(catalog.map((e) => e.kind))

    expect([...kinds].sort()).toEqual(['bodyweight', 'cardio', 'strength', 'timed'])
  })
})
